package com.rpb.reservation.workforce.payroll;
import static com.rpb.reservation.workforce.payroll.PayrollDtos.*;
import static org.assertj.core.api.Assertions.*;
import com.rpb.reservation.workforce.application.WorkforceDtos.Employee;
import com.rpb.reservation.workforce.statutory.*;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.Test;
class PayrollLineageTest {
 final UUID employee=UUID.randomUUID(),company=UUID.randomUUID(),store=UUID.randomUUID(),schedule=UUID.randomUUID();final YearMonth month=YearMonth.of(2026,10);
 SourceRef ref(UUID id,String state,long actual,long approved,Instant start,Instant end){return new SourceRef(id,store,month.atDay(1),2,"fp",approved,0,0,true,new SourceEvidence(actual,state,state.equals("current")?approved:null,start,end,List.of(id+":LATE")));}
 PayrollLine calculate(List<SourceRef> refs,List<Item> fixed,List<Item> adjustments,String mode){
  var e=new Employee(employee,"E","Synthetic","","","",month.atDay(1),null,"active",company,month.atDay(1),null,List.of(),null,1,false);
  var r=new Rule((mode.equals("fixed")||mode.equals("manual_monthly"))?"monthly":"hourly",(mode.equals("fixed")||mode.equals("manual_monthly"))?"3000":"20","8","44",false,"1.5",fixed,mode.equals("fixed")?new Generation("fixed",List.of()):null);
  var p=new PayProfile(UUID.randomUUID(),company,employee,"Synthetic",month.atDay(1),UUID.randomUUID(),1,r,new StatutoryDtos.CpfProfile("foreign",null,null,"GG",""),1);
  var i=new LineInput(employee,1,"1","1",true,true,adjustments,"reviewed",null,mode.equals("fixed")?"fixed":null);
  var t=OfficialStatutoryTemplates.forYear(2026);var policy=new StatutoryPolicies.Policy(UUID.randomUUID(),t.name(),2026,"SGD",t.effectiveFrom(),t.effectiveTo(),true,1,t.config());
  var s=new PayrollSources.CapturedLine(e,p,i,refs,List.of(),false);
  return new PayrollCalculationService(Clock.fixed(Instant.EPOCH,ZoneOffset.UTC)).calculate(new PayrollSources.Capture("fp",new PayrollRepository.CompanyInfo("Synthetic","TEST",7,true,1),List.of(s),Set.of(store),policy),month).lines().getFirst();
 }
 @Test void lateHoursHaveActualApprovedAndPayableEvidenceWithoutSecondDeduction(){var l=calculate(List.of(ref(schedule,"current",27000,27000,Instant.EPOCH,Instant.EPOCH.plusSeconds(27000))),List.of(),List.of(),"");assertThat(l.basicPay()).isEqualTo("150.00");assertThat(l.deductions()).isEqualTo("0.00");assertThat(l.hours()).isNotNull();assertThat(l.hours().actualSeconds()).isEqualTo(27000);assertThat(l.hours().approvedSeconds()).isEqualTo(27000);assertThat(l.components().getFirst().lineage().quantity()).isEqualTo("27000");}
 @Test void staleApprovalDoesNotPretendToBeApprovedZero(){var l=calculate(List.of(ref(schedule,"stale",28000,0,Instant.EPOCH,Instant.EPOCH.plusSeconds(28000))),List.of(),List.of(),"");assertThat(l.hours()).isNotNull();assertThat(l.hours().actualSeconds()).isEqualTo(28000);assertThat(l.hours().approvedSeconds()).isNull();assertThat(l.hours().approvalState()).isEqualTo("stale");}
 @Test void fixedSalaryDoesNotInventHours(){var l=calculate(List.of(),List.of(),List.of(),"fixed");assertThat(l.basicPay()).isEqualTo("3000.00");assertThat(l.hours()).isNotNull();assertThat(l.hours().approvalState()).isEqualTo("not_applicable");assertThat(l.hours().actualSeconds()).isNull();}
 @Test void duplicateScheduleAndOverlappingActualIntervalsBlockRatherThanTrim(){var a=ref(schedule,"current",7200,7200,Instant.EPOCH,Instant.EPOCH.plusSeconds(7200));assertThat(calculate(List.of(a,a),List.of(),List.of(),"").issues()).contains("SOURCE_DUPLICATE");var b=ref(UUID.randomUUID(),"current",7200,7200,Instant.EPOCH.plusSeconds(3600),Instant.EPOCH.plusSeconds(10800));assertThat(calculate(List.of(a,b),List.of(),List.of(),"").issues()).contains("SOURCE_ACTUAL_OVERLAP");}
 @Test void sameProfileMayHaveTwoIdenticalAllowancesButSameItemCannotBeConsumedTwice(){UUID a=UUID.randomUUID(),b=UUID.randomUUID();var x=new Item("Meal","ow_allowance","10",null,a,null);var y=new Item("Meal","ow_allowance","10",null,b,null);var l=calculate(List.of(),List.of(x,y),List.of(),"");assertThat(l.allowances()).isEqualTo("20.00");assertThat(l.components().get(2).lineage()).isNotNull();assertThat(l.components().get(2).lineage().sourceKeys()).isNotEqualTo(l.components().get(3).lineage().sourceKeys());assertThat(calculate(List.of(),List.of(x,x),List.of(),"").issues()).contains("ITEM_SOURCE_DUPLICATE");}
 @Test void attendanceDeductionNeedsIndependentExplanationButLegacyManualItemIsKept(){var source=new ItemSource("approved_work",schedule.toString(),2,schedule+":LATE","");var deduction=new Item("Late","deduction","10",null,UUID.randomUUID(),source);var refs=List.of(ref(schedule,"current",27000,27000,Instant.EPOCH,Instant.EPOCH.plusSeconds(27000)));assertThat(calculate(refs,List.of(),List.of(deduction),"").issues()).contains("ATTENDANCE_DEDUCTION_EXPLANATION_REQUIRED");assertThat(calculate(refs,List.of(),List.of(new Item("Legacy","deduction","10")),"").deductions()).isEqualTo("10.00");}
 @Test void oldJsonOmitsAllNewFields()throws Exception{var m=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules();String old="{\"label\":\"Meal\",\"kind\":\"ow_allowance\",\"amount\":\"10\"}";assertThat(m.writeValueAsString(m.readValue(old,Item.class))).isEqualTo(old);}
 @Test void boundaryRetainsStableItemAndSourceWhileRejectingMalformedReferences(){var id=UUID.randomUUID();var source=new ItemSource("approved_work",schedule.toString(),2,schedule+":LATE","Independent contractual charge");var item=new Item("Charge","deduction","10",null,id,source);var clean=PayrollValues.items(List.of(item)).getFirst();assertThat(clean.itemId()).isEqualTo(id);assertThat(clean.source()).isEqualTo(source);}
 @Test void eventConsumptionIsSharedAcrossProfileAndMonthlyInput(){var ref=ref(schedule,"current",27000,27000,Instant.EPOCH,Instant.EPOCH.plusSeconds(27000));var source=new ItemSource("approved_work",schedule.toString(),2,schedule+":LATE","Independent contract penalty");var a=new Item("A","deduction","10",null,UUID.randomUUID(),source);var b=new Item("B","deduction","10",null,UUID.randomUUID(),source);assertThat(calculate(List.of(ref),List.of(a),List.of(b),"").issues()).contains("ITEM_SOURCE_DUPLICATE");}
 @Test void fixedBasicEvidenceReferencesFullProfileWithoutAttendanceUnits(){var l=calculate(List.of(),List.of(),List.of(),"fixed");var evidence=l.components().getFirst().lineage();assertThat(evidence.origin()).isEqualTo("profile");assertThat(evidence.formula()).isEqualTo("fixed_full_v1");assertThat(evidence.quantity()).isEqualTo("1");assertThat(evidence.unit()).isEqualTo("fixed_salary");assertThat(evidence.proration()).isEqualTo("full");}
 @Test void statutoryAmountsHavePolicyEvidence(){var l=calculate(List.of(ref(schedule,"current",27000,27000,Instant.EPOCH,Instant.EPOCH.plusSeconds(27000))),List.of(),List.of(),"");assertThat(l.components()).anySatisfy(x->{assertThat(x.kind()).isEqualTo("employee_cpf");assertThat(x.lineage().origin()).isEqualTo("statutory");});}
 @Test void oldStatutoryResultConstructorOmitsNewTrace()throws Exception{var zero=java.math.BigDecimal.ZERO;var result=new StatutoryDtos.Result(zero,zero,zero,"OLD",zero);assertThat(new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules().writeValueAsString(result)).doesNotContain("trace");}
 @Test void configurationSourcesCannotClaimAnAttendanceEvent(){var source=new ItemSource("profile",UUID.randomUUID().toString(),1,schedule+":LATE",null);assertThatThrownBy(()->PayrollValues.items(List.of(new Item("Charge","deduction","10",null,UUID.randomUUID(),source)))).isInstanceOf(com.rpb.reservation.workforce.domain.WorkforceException.class);}
 @Test void fixedRecurringEvidenceDoesNotExposeSyntheticOneDayProration(){var l=calculate(List.of(),List.of(new Item("Meal","ow_allowance","10")),List.of(),"fixed");assertThat(l.components().get(2).lineage().proration()).isEqualTo("full");}
 @Test void previousMonthContextCannotFundAnExplicitCurrentMonthItem(){for(String origin:List.of("approved_work","paid_leave")){var evidence=new SourceEvidence(27000,"current",27000L,Instant.EPOCH,Instant.EPOCH.plusSeconds(27000),List.of(schedule+":LATE"));var context=new SourceRef(schedule,store,month.atDay(1).minusDays(1),2,"fp",27000,3600,0,false,evidence);var source=new ItemSource(origin,schedule.toString(),2,null,null);var item=new Item("Old event","ow_allowance","10",null,UUID.randomUUID(),source);assertThat(calculate(List.of(context),List.of(item),List.of(),"").issues()).as(origin).contains("ITEM_SOURCE_INVALID");}}
 @Test void reviewedManualMonthlyUnitsAreInputEvidenceRatherThanApprovedAttendance(){var l=calculate(List.of(),List.of(),List.of(),"manual_monthly");assertThat(l.basicPay()).isEqualTo("3000.00");assertThat(l.components().getFirst().lineage().origin()).isEqualTo("monthly_input");assertThat(l.components().getFirst().lineage().sourceKeys()).anyMatch(k->k.startsWith("monthly_input:"));}
}
